package io.cryptocontrol.whitebird.models;

import lombok.Data;

/**
 * @author enamakel@cryptocontrol.io
 */
@Data
public class CurrencyPair {
    private Currency primary;
    private Currency secondary;

    public static final CurrencyPair LTCBTC = new CurrencyPair(Currency.LTC, Currency.BTC);
    public static final CurrencyPair BTCUSD = new CurrencyPair(Currency.BTC, Currency.USD);


    private CurrencyPair(Currency p, Currency s) {
        this.primary = p;
        this.secondary = s;
    }


    public String toString() {
        return "" + primary + "/" + secondary;
    }
}

package io.cryptocontrol.whitebird.models;

import lombok.Data;

/**
 * @author enamakel@cryptocontrol.io
 */
@Data
public class Quote {
    private Exchange exchange;
    private CurrencyPair currencyPair;
    private Double bid;
    private Double ask;
    private Double lastPrice;


    public Quote(Exchange exchange, CurrencyPair currencyPair, Double bid, Double ask, Double lastPrice) {
        this.exchange = exchange;
        this.currencyPair = currencyPair;
        this.bid = bid;
        this.ask = ask;
        this.lastPrice = lastPrice;
    }


    public Quote(Exchange exchange, CurrencyPair currencyPair, Double bid, Double ask) {
        this(exchange, currencyPair, bid, ask, null);
    }


    public String toString() {
        if (lastPrice != null)
            return String.format("%10s %s [bid: %.04f | ask: %.04f | last: %.04f]", exchange, currencyPair, bid, ask,
                    lastPrice);
        return String.format("%10s %s [bid: %.04f | ask: %.04f]", exchange, currencyPair, bid, ask);
    }
}

package io.cryptocontrol.whitebird.models;

import lombok.Data;

/**
 * @author enamakel@cryptocontrol.io
 */
@Data
public class Opportunity {
    Exchange shortExchange;
    Exchange longExchange;

    // The prices at which the trade is entered
    Double priceLongIn;
    Double priceShortIn;

    // The prices at which the trades are being exited
    Double priceLongOut;
    Double priceShortOut;

    Double exitTarget;

    // A simple number that should be incrememnted for every unit of time we are querying for an arbitrage opportunity.
    // Ideally this should determined if our trade is gotten too old and whether we force an exit or not.
    Integer timePeriod = 0;

    Double trailingSpread;
    Integer trailingWaitCount;


    public String toString() {
        // printing an opportunity that has found an exit
        if (priceLongOut != null && priceShortOut != null) {
            Double spread = (priceShortOut - priceLongOut) / priceLongOut;
            return String.format("%s @ %.02f->%.02f [long] | %s @ %.02f->%.02f [short] | %.02f%% [exit target] | %.02f%% [exit spread] ",
                    longExchange, priceLongIn, priceLongOut, shortExchange, priceShortIn, priceShortOut, exitTarget, spread);
        }

        // printing an opportunity that has just found an entry
        Double spread = (priceShortIn - priceLongIn) / priceLongIn;
        return String.format("%s @ %.02f [long] | %s @ %.02f [short] | %.02f%% [exit target]  | %.02f%% [entry spread]", longExchange,
                priceLongIn, shortExchange, priceShortIn, exitTarget, spread);
    }
}

package io.cryptocontrol.whitebird.models;

/**
 * @author enamakel@cryptocontrol.io
 */
public class Currency {
    private String name;

    public static final Currency BTC = new Currency("BTC");
    public static final Currency LTC = new Currency("LTC");
    public static final Currency USD = new Currency("USD");


    private Currency(String name) {
        this.name = name;
    }


    public String toString() {
        return name;
    }
}

package io.cryptocontrol.whitebird.models;

import lombok.Data;

import java.util.HashMap;
import java.util.Map;

@Data
public class Balances {
    Map<Currency, Double> map = new HashMap<>();


    public Double getBalance(Currency currency) {
        if (map.containsKey(currency)) return map.get(currency);
        return 0d;
    }


    public Double updateBalance(Currency currency, Double balance) {
        return map.put(currency, balance);
    }
}

